#include "c0/driver.h"
#include "parser.tab.hpp"
#include <cstdio>
#include <fstream>
#include <iostream>

// Declarations provided by Flex
typedef void* yyscan_t;
int yylex_init_extra(c0::Driver* user_defined, yyscan_t* scanner);
int yylex_destroy(yyscan_t scanner);
struct yy_buffer_state;
typedef yy_buffer_state* YY_BUFFER_STATE;
YY_BUFFER_STATE yy_scan_string(const char* str, yyscan_t scanner);
void yy_delete_buffer(YY_BUFFER_STATE b, yyscan_t scanner);
void yyset_in(FILE* in_str, yyscan_t scanner);

// Generated by Bison
int yyparse(yyscan_t scanner, c0::Driver* driver);

namespace c0 {

Driver::Driver() = default;
Driver::~Driver() = default;

void Driver::report_error(const SourceLocation& loc, const std::string& msg) {
    diagnostics_.push_back({current_file, loc, msg});
}

void Driver::report_error(int line, int col, const std::string& msg) {
    report_error(SourceLocation{line, col}, msg);
}

void Driver::print_diagnostics(std::ostream& os) const {
    for (const auto& diag : diagnostics_) {
        os << diag.filename << ":" << diag.location.line << ":" << diag.location.col
           << ": error: " << diag.message << "\n";
    }
}

bool Driver::is_type_name(const std::string& name) const {
    return type_names_.find(name) != type_names_.end();
}

void Driver::add_type_name(const std::string& name) {
    type_names_.insert(name);
}

bool Driver::parse_file(const std::string& filepath) {
    current_file = filepath;
    column = 1;
    comment_depth = 0;

    FILE* fp = std::fopen(filepath.c_str(), "r");
    if (!fp) {
        report_error(SourceLocation{1, 1}, "Could not open file: " + filepath);
        return false;
    }

    yyscan_t scanner;
    if (yylex_init_extra(this, &scanner) != 0) {
        std::fclose(fp);
        report_error(SourceLocation{1, 1}, "Failed to initialize scanner");
        return false;
    }

    yyset_in(fp, scanner);
    int res = yyparse(scanner, this);
    yylex_destroy(scanner);
    std::fclose(fp);

    return (res == 0) && diagnostics_.empty();
}

bool Driver::parse_string(const std::string& code, const std::string& sourcename) {
    current_file = sourcename;
    column = 1;
    comment_depth = 0;

    yyscan_t scanner;
    if (yylex_init_extra(this, &scanner) != 0) {
        report_error(SourceLocation{1, 1}, "Failed to initialize scanner");
        return false;
    }

    YY_BUFFER_STATE buf = yy_scan_string(code.c_str(), scanner);
    int res = yyparse(scanner, this);
    yy_delete_buffer(buf, scanner);
    yylex_destroy(scanner);

    return (res == 0) && diagnostics_.empty();
}

} // namespace c0
